import { test, expect } from '@playwright/test';

// (deliberately weak first attempt — deletes in the All filter, where the bug does not show)
test('deleting a todo removes it', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  const input = page.getByPlaceholder('What needs doing?');
  for (const t of ['Buy milk', 'Walk dog', 'Pay rent']) {
    await input.fill(t);
    await page.getByRole('button', { name: 'Add' }).click();
  }
  await page.getByLabel('Delete Pay rent').click();
  await expect(page.getByText('Pay rent')).toHaveCount(0);
  await expect(page.getByText('Walk dog')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('deleting a todo in the Active filter removes that todo, not another one', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();

  const input = page.getByPlaceholder('What needs doing?');
  for (const t of ['Buy milk', 'Walk dog', 'Pay rent']) {
    await input.fill(t);
    await page.getByRole('button', { name: 'Add' }).click();
  }

  // complete the first one so the Active filter hides it (indices diverge)
  await page.getByLabel('Mark Buy milk done').click();
  await page.getByRole('button', { name: 'Active' }).click();
  await expect(page.locator('#list li')).toHaveCount(2);

  await page.getByLabel('Delete Pay rent').click();

  // symptom from the recording: 'Walk dog' vanished instead of 'Pay rent'
  await expect(page.getByText('Walk dog')).toBeVisible();
  await expect(page.getByText('Pay rent')).toHaveCount(0);

  await page.getByRole('button', { name: 'All' }).click();
  await expect(page.locator('#list li')).toHaveCount(2);
  await expect(page.getByText('Buy milk')).toBeVisible();
  await expect(page.getByText('Walk dog')).toBeVisible();
});
